package com.collabspace.entity;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="messages",indexes={@Index(name="idx_msg_channel_created",columnList="channel_id,created_at"),@Index(name="idx_msg_sender",columnList="sender_id")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Message { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Channel channel; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User sender; @Column(nullable=false,length=4000) private String content; @ManyToOne(fetch=FetchType.LAZY) private Message replyTo; @Column(nullable=false,updatable=false) @Builder.Default private Instant createdAt=Instant.now(); @Column(nullable=false) @Builder.Default private Instant updatedAt=Instant.now(); @Column(nullable=false) @Builder.Default private boolean edited=false; @Column(nullable=false) @Builder.Default private boolean deleted=false; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private ReadStatus readStatus=ReadStatus.SENT; @PreUpdate void touch(){updatedAt=Instant.now();} }